css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; top: 19%; width: 24%; height: 62%; background: linear-gradient(var(--accent), var(--accent-2)); }
.loader span:nth-child(1) { left: 26%; animation: morph-left calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
.loader span:nth-child(2) { left: 50%; animation: morph-right calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
@keyframes morph-left { 0%, 18% { clip-path: polygon(0 0, 100% 24%, 100% 76%, 0 100%); transform: translateX(0); } 46%, 72% { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); transform: translateX(-16%); } 94%, 100% { clip-path: polygon(0 0, 100% 24%, 100% 76%, 0 100%); transform: translateX(0); } }
@keyframes morph-right { 0%, 18% { clip-path: polygon(0 24%, 100% 49%, 100% 51%, 0 76%); transform: translateX(0); } 46%, 72% { clip-path: polygon(0 0, 100% 0, 100% 100%, 0 100%); transform: translateX(16%); } 94%, 100% { clip-path: polygon(0 24%, 100% 49%, 100% 51%, 0 76%); transform: translateX(0); } }
